fn sqrt(x: Float) -> Float {
    let mut acc = 0.0
    let mut k = 1.0
    loop
    let y = (acc + k) / 2.0
    if (y - acc) < 0.000001 {
        breaky
    }
    acc = y
    k = k / 2.0
    loop
    acc
}

